def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find a full straight line of 2s, the axis. The non-background object
    # lies on one side; draw an 8 line just beyond its far edge.
    row_axis = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    col_axis = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if row_axis is not None:
        obj_rows = [r for r in range(h) for c in range(w) if grid[r][c] not in (2, 3)]
        if obj_rows:
            if max(obj_rows) < row_axis:
                target = min(obj_rows) - 1
            else:
                target = max(obj_rows) + 1
            if 0 <= target < h:
                out[target] = [8] * w
    elif col_axis is not None:
        bg = grid[0][0] if grid[0][0] != 2 else next((v for row in grid for v in row if v not in (2, 7)), 5)
        obj_cols = [c for r in range(h) for c in range(w) if grid[r][c] not in (2, bg)]
        if obj_cols:
            if max(obj_cols) < col_axis:
                target = min(obj_cols) - 1
            else:
                target = max(obj_cols) + 1
            if 0 <= target < w:
                for r in range(h):
                    out[r][target] = 8
    return out
